// 中国移动云盘 (China Mobile Cloud Drive / MClaw) Provider Plugin for Magpie & OpenCode
// 核心能力：
// 1. 实时算力燃料 Token 额度监控（每月送 50万~3000万 Tokens）
// 2. 每日自动签到与 AI 豆（原云朵）任务中心领取
// 3. 动态模型库（DeepSeek-R1 满血版 671B、通义千问系列、火山引擎豆包等）
// 4. 标准 OpenAI 兼容 SSE 反代网关（支持流式打字机与 DeepSeek-R1 深度思考 reasoning_content 回传）
// 5. 双鉴权模式：支持网页一键引导向导与客户端弹窗直接粘贴 Authorization/Cookie

import { createServer } from "node:http"
import { exec } from "node:child_process"

const PROVIDER = "mcloud"
const PROVIDER_NAME = "中国移动云盘 (MClaw)"
const MCLOUD_BASE = "https://yun.139.com"
const MCLOUD_API_BASE = "https://api.caiyun.feixin.10086.cn"
const MCLOUD_ICON = "data:image/png;base64,"
const NPM = "@ai-sdk/openai-compatible"

// 移动云盘 MClaw 官方模型表
const DEFAULT_MODELS = [
  { id: "mclaw-auto", name: "MClaw 智能助手 (Auto)", context: 131072, multiplier: "1.0x", reasoning: true, desc: "移动云盘 MClaw 智能路由，自动匹配最佳大模型" },
  { id: "deepseek-r1", name: "DeepSeek-R1 (满血版 671B)", context: 65536, multiplier: "1.0x", reasoning: true, desc: "国产顶级推理大模型，满血 671B 参数，具备深度思考链" },
  { id: "deepseek-v3", name: "DeepSeek-V3", context: 65536, multiplier: "0.2x", reasoning: false, desc: "DeepSeek 全功能通用大模型，响应敏捷，性价比极高" },
  { id: "qwen3.8_max", name: "通义千问 Qwen3.8-Max", context: 131072, multiplier: "0.8x", reasoning: true, desc: "阿里百炼最强全尺寸旗舰模型，超长上下文与多任务处理" },
  { id: "qwen3.7_plus", name: "通义千问 Qwen3.7-Plus", context: 131072, multiplier: "0.5x", reasoning: true, desc: "阿里百炼高性能通用大模型，逻辑代码写作均衡" },
  { id: "qwen3.5_plus", name: "通义千问 Qwen3.5-Plus", context: 131072, multiplier: "0.2x", reasoning: false, desc: "高性价比千问基座模型，适合轻量快速对话" },
  { id: "doubao-seed-2.1-pro", name: "火山引擎豆包 2.1-Pro", context: 131072, multiplier: "0.5x", reasoning: true, desc: "字节跳动豆包旗舰模型，擅长复杂推理与中文语境" },
  { id: "doubao-pro", name: "火山引擎豆包 Pro", context: 131072, multiplier: "0.3x", reasoning: false, desc: "火山引擎豆包通用模型，快速高效" },
  { id: "glm-5.3", name: "智谱清言 GLM-5.3", context: 131072, multiplier: "0.75x", reasoning: true, desc: "智谱 AI 新一代大模型，中英文双语能力强悍" },
]

function configModels() {
  return Object.fromEntries(
    DEFAULT_MODELS.map((m) => [
      m.id,
      {
        name: `${m.name} (${m.multiplier})`,
        limit: { context: m.context, output: 8192 },
        tool_call: true,
        ...(m.reasoning ? { reasoning: true, variants: ["low", "high", "max"] } : {}),
      },
    ])
  )
}

function modelOf(provider, m) {
  const isReasoning = !!(m.reasoning || (m.reasoning_efforts && m.reasoning_efforts.length > 0))
  const multiplierText = m.multiplier ? ` [${m.multiplier}]` : ""
  return {
    id: m.id || m.key,
    providerID: provider.id,
    name: `${m.name}${multiplierText}`,
    api: { id: m.id || m.key, url: `${MCLOUD_BASE}/api`, npm: NPM },
    status: "active",
    headers: {},
    options: {},
    cost: { input: 0, output: 0, cache: { read: 0, write: 0 } },
    limit: { context: m.max_context_tokens || m.context || 131072, output: m.max_new_tokens || 8192 },
    capabilities: {
      temperature: true,
      reasoning: isReasoning,
      attachment: !!m.support_multimodal,
      toolcall: true,
      input: { text: true, image: !!m.support_multimodal, audio: false, video: false, pdf: false },
      output: { text: true, image: false, audio: false, video: false, pdf: false },
      interleaved: false,
    },
    release_date: "",
    variants: isReasoning ? ["low", "high", "max"] : [],
  }
}

// 解析用户鉴权信息（兼容 Basic Authorization、Web Cookie 与自定义容器 BaseURL）
function resolveAuth(auth) {
  if (!auth) return { authorization: "", cookie: "", account: "", customEndpoint: "" }

  const rawKey = (auth.key || auth.access || auth.token || "").trim()
  const metadata = auth.metadata || {}
  const account = metadata.account || auth.accountId || ""
  const customEndpoint = metadata.customEndpoint || ""

  let authorization = ""
  let cookie = ""

  if (rawKey.startsWith("Basic ") || rawKey.startsWith("Bearer ")) {
    // 手机 App 抓包提取的 Basic Authorization
    const parts = rawKey.split("#")
    authorization = parts[0].trim()
  } else if (rawKey.includes("jwtToken=") || rawKey.includes("caiyun_token=") || rawKey.includes(";")) {
    // 网页版 Cookie
    cookie = rawKey
  } else if (rawKey.length > 30 && !rawKey.includes(" ")) {
    // 纯 token，拼装为通用 Header 与 Cookie
    authorization = `Bearer ${rawKey}`
    cookie = `jwtToken=${rawKey}; caiyun_token=${rawKey}`
  }

  if (metadata.cookie) cookie = metadata.cookie
  if (metadata.authorization) authorization = metadata.authorization

  return { authorization, cookie, account, customEndpoint }
}

function getTodayString() {
  const d = new Date()
  const year = d.getFullYear()
  const month = String(d.getMonth() + 1).padStart(2, "0")
  const day = String(d.getDate()).padStart(2, "0")
  return `${year}-${month}-${day}`
}

