                    <div class="card">
                      <h2>🇨🇳 中国移动云盘 (MClaw) 授权向导</h2>
                      <p>每月畅享 <b>50万~3000万 Tokens</b> 算力燃料，支持 DeepSeek-R1 满血版、通义千问等主流大模型。</p>

                      <div class="step">
                        <b>方式 1：手机 App 抓包（推荐，长久稳定）</b><br>
                        打开移动云盘 App，抓取任意接口（如 <code>authTokenRefresh.do</code>），复制请求头中的 <code>Authorization: Basic ...</code>。
                      </div>

                      <div class="step">
                        <b>方式 2：电脑网页版 Cookie</b><br>
                        登录 <a href="https://yun.139.com" target="_blank" style="color: #0085D0;">yun.139.com</a>，按 <code>F12</code> -> 【应用 / Application】->【Cookie】，复制 <code>jwtToken</code> 或完整 Cookie。
                      </div>

                      <form action="/callback" method="GET">
                        <label><b>移动云盘凭证（Authorization 或 Cookie）：</b></label>
                        <textarea name="auth" rows="3" placeholder="粘贴形如 Basic YWJj... 或 jwtToken=eyJ..." required autofocus></textarea>

                        <div style="margin-top: 14px;">
                          <label><b>手机号码（可选，用于配额看板展示）：</b></label>
                          <input name="phone" type="text" placeholder="如 13800138000" />
                        </div>

                        <div style="margin-top: 14px;">
                          <label><b>自定义 MClaw 容器地址（可选，如开通了 OpenClaw 容器）：</b></label>
                          <input name="endpoint" type="text" placeholder="如 http://127.0.0.1:18789 (默认留空即可)" />
                        </div>

                        <button type="submit">确认提交并完成授权</button>
                      </form>
                    </div>
                  </body>
                  </html>
                `)
              }
            })

            await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve))
            const port = server.address().port
            const authUrl = `http://127.0.0.1:${port}/`

            exec(process.platform === "win32" ? `start ${authUrl}` : `open ${authUrl}`)

            return {
              url: authUrl,
              instructions: "请在自动打开的浏览器向导页中输入中国移动云盘凭证",
              method: "auto",
              callback: () => done,
            }
          },
        },
        {
          type: "api",
          label: "直接粘贴凭据 (在 Magpie 弹窗中输入)",
          prompts: [
            {
              key: "auth",
              label: "移动云盘凭据 (Authorization / Cookie)",
              type: "password",
              placeholder: "粘贴 Basic YWJj... 或 jwtToken=...",
            },
            {
              key: "phone",
              label: "绑定手机号 (可选)",
              type: "text",
              placeholder: "用于在 Quota 面板显示账户标识",
            },
            {
              key: "endpoint",
              label: "自定义容器端点 (可选，默认使用云盘接口)",
              type: "text",
              placeholder: "例如 http://127.0.0.1:18789",
            },
          ],
          async authorize(inputs) {
            const authVal = String(inputs?.auth ?? "").trim()
            const phone = String(inputs?.phone ?? "").trim()
            const endpoint = String(inputs?.endpoint ?? "").trim()

            if (!authVal) return { type: "failed", error: "请输入有效的移动云盘登录凭据" }

            return {
              type: "success",
              key: authVal,
              metadata: {
                authorization: authVal.startsWith("Basic ") ? authVal : "",
                cookie: !authVal.startsWith("Basic ") ? authVal : "",
                account: phone || "移动云盘用户",
                customEndpoint: endpoint,
              },
              accountId: phone || "移动云盘用户",
            }
          },
        },
      ],
    },
  }
}

export default MCloudAuthPlugin
